-- ══════════════════════════════════════════════════════════════
-- Migration 026: Standards-driven content generation
--
-- Creates primer+task pairs for each of the 25 education
-- standards that currently have 0 aligned tasks.
-- Each pair is aligned to its target standard via the
-- alignment tables.
-- ══════════════════════════════════════════════════════════════

DO $$
DECLARE
  u_owner UUID;
  p UUID; t UUID; std_id UUID;
BEGIN
  SELECT id INTO u_owner FROM public.users WHERE email = 'mark.keith@gmail.com' LIMIT 1;
  IF u_owner IS NULL THEN
    SELECT id INTO u_owner FROM public.users WHERE role = 'admin' LIMIT 1;
  END IF;


  -- ═══════════════════════════════════════════════════════════
  -- NGSS GAPS (10 standards)
  -- ═══════════════════════════════════════════════════════════

  -- K-ESS2-1: Weather patterns (K, data_collection)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Watching the Weather', '{"text":"Weather is what the sky and air are doing right now. Is it sunny or cloudy? Warm or cold? Windy or still? Scientists watch weather every day and write down what they see. After many days, they can see patterns — like how spring is often rainy and summer is often hot.","items":["Sunny: the sun is shining, few clouds","Cloudy: clouds cover most of the sky","Rainy: water falls from clouds","Windy: you can feel air moving"]}', 'science_nature', 0, 2, true, 'independent', 'any', 2, ARRAY['weather','patterns','observation','K-ESS2-1'], ARRAY['young_scientist'], ARRAY['Observe and describe daily weather conditions','Identify weather patterns over time'], 3, true, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Weather Watch Report', 'science_nature', 'data_collection', '{"question":"Look at the sky and feel the air right now. Record: (1) Is it sunny, partly cloudy, or cloudy? (2) Is it warm, cool, or cold? (3) Is it windy, breezy, or calm? (4) Can you see any rain or snow? Draw a simple picture of today''s weather.","hints":["Look UP at the sky first","Hold your hand out — can you feel wind?","Is the sun making shadows? That means sunny!","Every kind of weather is interesting to a scientist!"]}', 0, 2, 1, true, 'independent', 'any', 2, ARRAY['weather','observation','patterns','K-ESS2-1'], ARRAY['young_scientist'], ARRAY['Record weather observations using multiple senses'], 5, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'K-ESS2-1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- 2-ESS2-3: Where water is found (2, photo_observation)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Water Is Everywhere', '{"text":"Water is found all over Earth — in oceans, rivers, lakes, puddles, clouds, and even underground! Water can be a liquid (in a glass), a solid (ice), or a gas (steam). Most of Earth''s water is in the oceans. Fresh water that we drink comes from rivers, lakes, and underground wells.","items":["Oceans: most of Earth''s water (salty)","Rivers and lakes: fresh water we can see","Underground: water hidden in soil and rocks","Clouds: tiny water droplets floating in air"]}', 'science_nature', 0, 2, true, 'independent', 'any', 2, ARRAY['water','states_of_matter','earth_science','2-ESS2-3'], ARRAY['young_scientist','nature_detective'], ARRAY['Identify places where water is found','Recognize that water can be solid or liquid'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Water Finder', 'science_nature', 'photo_observation', '{"question":"Find 3 different places where you can see water right now (or signs that water has been here). Take a photo of each. Water can be: a puddle, dew on grass, a drinking fountain, a wet spot, a drain, condensation on a window, or even clouds! Is the water liquid, solid (ice), or gas (steam)?","hints":["Look on the ground for puddles or wet spots","Check leaves — do they have water drops?","Is there a fountain, hose, or sprinkler nearby?","Clouds are made of tiny water droplets!"]}', 0, 2, 1, true, 'independent', 'any', 2, ARRAY['water','observation','states_of_matter','2-ESS2-3'], ARRAY['young_scientist'], ARRAY['Find and photograph water in different locations'], 7, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '2-ESS2-3';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- 3-LS4-3: Habitat survival (3, multiple_choice)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Surviving in a Habitat', '{"text":"Not every organism can survive in every habitat. A cactus thrives in the desert but would rot in a swamp. A fish needs water but would die on land. Organisms survive when their traits match what the habitat provides: the right temperature, food, water, and shelter. When the habitat changes, organisms that cannot adapt may disappear.","items":["Organisms need: food, water, shelter, space","Traits must match the habitat","Desert organisms: thick skin, store water, active at night","Wetland organisms: webbed feet, waterproof feathers, gills"]}', 'science_nature', 3, 5, true, 'independent', 'any', 4, ARRAY['habitats','survival','adaptation','traits','3-LS4-3'], ARRAY['nature_detective'], ARRAY['Explain why some organisms survive in a habitat and others cannot'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Habitat Match Challenge', 'science_nature', 'multiple_choice', '{"question":"Look at your current location. Which of these organisms would survive BEST here?","options":["A polar bear (needs freezing temperatures and ice)","A cactus (needs hot, dry conditions with sandy soil)","A local bird you can actually see or hear right now","A deep-sea fish (needs ocean pressure and darkness)"],"correct_answer":"A local bird you can actually see or hear right now","hints":["Think about the temperature right now — too hot or cold for some","What food and water sources are available here?","Which option is actually adapted to YOUR local environment?","The organism already living here is the best answer!"]}', 3, 5, 2, true, 'independent', 'any', 4, ARRAY['habitats','survival','adaptation','3-LS4-3'], ARRAY['nature_detective'], ARRAY['Identify which organisms suit the current habitat'], 3, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '3-LS4-3';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- 4-LS1-1: Plant/animal structures (4, sketch_draw)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Structures for Survival', '{"text":"Every plant and animal has structures (body parts) that help it survive. Thorns protect plants from being eaten. Deep roots reach underground water. Wings let birds escape predators. Thick fur keeps mammals warm. These structures developed over millions of years through natural selection — organisms with helpful structures survived and passed them to their offspring.","items":["External structures: thorns, fur, claws, bark, petals","Internal structures: roots, veins, bones, lungs","Protective structures: shells, thorns, camouflage colors","Reproductive structures: flowers, seeds, eggs"]}', 'science_nature', 3, 5, true, 'independent', 'any', 5, ARRAY['structures','survival','plants','animals','4-LS1-1'], ARRAY['nature_detective','field_scientist'], ARRAY['Identify structures that help organisms survive','Explain how structures support specific survival functions'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Survival Structure Sketch', 'science_nature', 'sketch_draw', '{"question":"Find one plant OR one animal near you. Sketch it and label at least 4 structures (body parts) that help it survive. For each structure, write one sentence explaining HOW it helps. Example: Bark → protects the trunk from insects and weather.","hints":["Plants: roots, stems, leaves, bark, thorns, flowers, seeds","Animals: legs, wings, eyes, fur, claws, beak, antennae","Think about protection, getting food, getting water, reproducing","Even a simple weed has survival structures — look closely!"]}', 3, 5, 2, true, 'independent', 'any', 5, ARRAY['structures','survival','observation','sketch','4-LS1-1'], ARRAY['nature_detective'], ARRAY['Identify and illustrate survival structures on a real organism'], 8, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '4-LS1-1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- 4-ESS2-2: Earth's features from maps (4, short_text)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Reading Earth''s Surface', '{"text":"Maps reveal patterns in Earth''s features. Mountains line up in ranges. Rivers follow valleys. Coastlines curve where waves erode rock. Volcanoes cluster along plate boundaries. By studying maps, scientists can predict where earthquakes might happen, where floods are likely, and where to find certain minerals. The patterns tell the story of how Earth''s surface formed.","items":["Mountain ranges: form along plate boundaries","River patterns: follow the lowest ground (gravity)","Coastline shapes: carved by waves and currents","Flat plains: often ancient sea floors or flood deposits"]}', 'science_nature', 3, 5, true, 'independent', 'any', 5, ARRAY['earth_features','maps','patterns','geology','4-ESS2-2'], ARRAY['explorer','field_scientist'], ARRAY['Identify patterns in Earth''s surface features','Use observations to describe landscape formation'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Landscape Pattern Finder', 'science_nature', 'short_text', '{"question":"Look at the landscape around you. Describe 2 patterns you can see in Earth''s surface: Are there hills? Flat areas? A valley? Water features? Which direction do slopes point? Write 3 sentences explaining what forces (water, wind, ice, humans) might have shaped this landscape over time.","correct_answer":null,"hints":["Flat areas were often shaped by water (ancient lakes or rivers)","Hills and valleys show where erosion carved the land","Look for evidence of human changes: cuts, fills, leveling","Mountains in the distance show tectonic forces at work"]}', 3, 5, 2, true, 'independent', 'any', 5, ARRAY['earth_features','patterns','landscape','4-ESS2-2'], ARRAY['explorer'], ARRAY['Describe and explain landscape patterns'], 5, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '4-ESS2-2';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- 5-PS1-1: Matter/particles (5, creative_writing)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'The Invisible World of Particles', '{"text":"Everything around you — rocks, air, water, your own body — is made of particles too small to see. These particles are constantly moving. In solids, particles vibrate in place (that is why rocks feel hard). In liquids, particles slide past each other (that is why water flows). In gases, particles fly freely in all directions (that is why air fills every space). Temperature is really a measure of how fast particles are moving.","items":["Solid: particles packed tight, vibrate in place","Liquid: particles close but slide freely","Gas: particles spread out, move fast in all directions","Temperature = particle speed"]}', 'science_nature', 4, 6, true, 'independent', 'any', 6, ARRAY['matter','particles','states_of_matter','physics','5-PS1-1'], ARRAY['field_scientist'], ARRAY['Describe matter as made of particles too small to see','Explain differences between solid, liquid, and gas at the particle level'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Particle Story', 'science_nature', 'creative_writing', '{"question":"Pick one object you can see (a rock, a puddle, the air, a leaf). Write a short story (5 sentences) from the perspective of ONE particle inside that object. Describe: What are you doing right now? (vibrating, flowing, flying?) Who are your neighbors? What happens when the temperature changes? What would happen if you were heated up or cooled down?","hints":["Rock particles vibrate but stay in place — like shaking in a crowd","Water particles slide past neighbors — like people in a swimming pool","Air particles zoom around freely — like balls bouncing in a room","Heating = moving faster; cooling = slowing down"]}', 4, 6, 3, true, 'independent', 'any', 6, ARRAY['matter','particles','perspective_writing','5-PS1-1'], ARRAY['field_scientist'], ARRAY['Apply particle model through creative perspective-taking'], 8, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '5-PS1-1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- 5-LS2-1: Matter movement in ecosystems (5, sketch_draw)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Matter Cycles Through Ecosystems', '{"text":"Matter does not disappear — it cycles. Plants take in CO2 and water to build their bodies (photosynthesis). Animals eat plants and use that matter for energy and growth. When organisms die, decomposers break them down, releasing nutrients back into the soil. Those nutrients feed new plants, and the cycle continues. Nothing is wasted in nature.","items":["Plants: absorb CO2 + water → build body + release O2","Animals: eat plants → use matter for growth + energy","Decomposers: break down dead organisms → nutrients return to soil","Cycle: soil nutrients → plants → animals → decomposers → soil"]}', 'science_nature', 4, 6, true, 'independent', 'any', 6, ARRAY['matter_cycling','ecosystem','decomposition','photosynthesis','5-LS2-1'], ARRAY['field_scientist','nature_detective'], ARRAY['Describe how matter moves among plants, animals, and decomposers'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Matter Cycle Diagram', 'science_nature', 'sketch_draw', '{"question":"Find evidence of the matter cycle at your location. Draw a diagram showing how matter moves from soil → plant → animal → decomposer → back to soil. Use REAL organisms you can see or find evidence of. Draw arrows showing the direction matter flows. Label at least one example of each: producer, consumer, decomposer.","hints":["Plants pull matter from soil through roots (producer)","An insect eating a leaf is a consumer","Mushrooms, mold, or rotting leaves show decomposition","Dead leaves on the ground are matter returning to the soil"]}', 4, 6, 3, true, 'independent', 'any', 6, ARRAY['matter_cycling','diagram','ecosystem','5-LS2-1'], ARRAY['field_scientist'], ARRAY['Diagram the cycling of matter through a real ecosystem'], 8, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '5-LS2-1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- 5-ESS2-1: Geosphere/biosphere interactions (5, data_collection)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Earth''s Systems Work Together', '{"text":"Earth has four interconnected systems: the geosphere (rocks, soil, land), hydrosphere (water), atmosphere (air), and biosphere (living things). They constantly interact. Rain (atmosphere) erodes rock (geosphere), carrying sediment to rivers (hydrosphere), which creates habitat for fish (biosphere). A volcanic eruption (geosphere) puts ash into the atmosphere, which affects climate and living things.","items":["Geosphere: rocks, soil, mountains, continents","Hydrosphere: oceans, rivers, lakes, groundwater, ice","Atmosphere: air, weather, climate","Biosphere: all living organisms"]}', 'science_nature', 4, 6, true, 'independent', 'any', 6, ARRAY['earth_systems','geosphere','biosphere','hydrosphere','atmosphere','5-ESS2-1'], ARRAY['field_scientist'], ARRAY['Describe how Earth''s four systems interact'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Earth Systems Interaction Hunt', 'science_nature', 'data_collection', '{"question":"Find ONE example of each of Earth''s four systems at your location: (1) Geosphere — a rock, soil, or landform, (2) Hydrosphere — water in any form, (3) Atmosphere — evidence of weather or air, (4) Biosphere — a living organism. Then describe ONE interaction between two of them. Example: rain (atmosphere) eroded this rock (geosphere).","hints":["Geosphere: look at the ground — soil, rocks, pavement (made from rock)","Hydrosphere: puddles, dew, wet soil, clouds, a drinking fountain","Atmosphere: feel the wind, notice temperature, look at clouds","Biosphere: any plant, animal, fungus, or evidence of one"]}', 4, 6, 3, true, 'independent', 'any', 6, ARRAY['earth_systems','interaction','observation','5-ESS2-1'], ARRAY['field_scientist'], ARRAY['Identify and connect Earth''s four systems at a real location'], 8, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '5-ESS2-1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- MS-ESS2-2: Geoscience processes (6-8, short_text)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Forces That Shape the Surface', '{"text":"Earth''s surface is constantly being reshaped by two types of forces. Constructive forces build up the surface: volcanic eruptions create new land, tectonic plates push mountains upward, and sediment deposits build deltas. Destructive forces wear it down: weathering breaks rock apart, erosion carries sediment away, and landslides move soil downhill. The landscape you see is the result of millions of years of these competing forces.","items":["Constructive: volcanism, mountain building, deposition","Destructive: weathering, erosion, landslides","Chemical weathering: water dissolves rock over time","Physical weathering: freeze-thaw cycles crack rock"]}', 'science_nature', 6, 8, true, 'independent', 'any', 6, ARRAY['geoscience','erosion','weathering','tectonics','MS-ESS2-2'], ARRAY['field_scientist'], ARRAY['Explain how constructive and destructive forces shape Earth''s surface'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Surface Change Evidence', 'science_nature', 'short_text', '{"question":"Find evidence of EITHER a constructive force (building up) OR a destructive force (wearing down) at your location. Describe: (1) What do you see? (2) Is it constructive or destructive? (3) What force caused it? (4) How long do you think this process took? Write 4-5 sentences with specific evidence.","correct_answer":null,"hints":["Erosion: worn paths, exposed roots, gullies, smooth rocks","Deposition: sediment piles, sand bars, alluvial fans","Weathering: cracked rocks, potholes, stained stone","Human-made changes count too: cuts, fills, retaining walls"]}', 6, 8, 3, true, 'independent', 'any', 6, ARRAY['geoscience','erosion','evidence','MS-ESS2-2'], ARRAY['field_scientist'], ARRAY['Identify and explain evidence of geoscience processes'], 5, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'MS-ESS2-2';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- MS-ESS3-3: Monitoring human impact (6-8, data_collection)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Measuring Our Footprint', '{"text":"Humans impact the environment in measurable ways: air and water pollution, habitat destruction, soil erosion from construction, light pollution, noise pollution, and waste accumulation. Scientists monitor these impacts by collecting data over time. The first step to solving environmental problems is measuring them accurately. If you can''t measure it, you can''t manage it.","items":["Air quality: particulates, CO2, ozone levels","Water quality: pH, dissolved oxygen, turbidity","Habitat: species counts before and after development","Waste: volume of litter per area, recycling rates"]}', 'science_nature', 6, 8, true, 'independent', 'any', 7, ARRAY['human_impact','environment','monitoring','sustainability','MS-ESS3-3'], ARRAY['field_scientist','urban_explorer'], ARRAY['Design a method for monitoring human environmental impact'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Human Impact Audit', 'science_nature', 'data_collection', '{"question":"Conduct a human impact audit of your immediate area (50m radius). Record: (1) Litter count: how many pieces visible? (2) Impervious surface: estimate % covered by concrete/asphalt vs natural ground, (3) Noise level 1-5, (4) Light pollution potential 1-5 (how many artificial lights visible?), (5) Evidence of habitat modification (paved over, landscaped, natural?). Score the area 1-10 for environmental health. What ONE change would improve it most?","hints":["Count litter carefully — small pieces count","Impervious surfaces prevent water absorption","More lights = more light pollution for nocturnal animals","Compare: what was this land before humans modified it?"]}', 6, 8, 3, true, 'independent', 'any', 7, ARRAY['human_impact','audit','data','environment','MS-ESS3-3'], ARRAY['field_scientist'], ARRAY['Collect data to assess human environmental impact'], 10, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'MS-ESS3-3';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;


  -- ═══════════════════════════════════════════════════════════
  -- CCSS-M GAPS (4 standards)
  -- ═══════════════════════════════════════════════════════════

  -- 2.G.A.1: Shape attributes (2, sorting_ordering)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Shapes Have Special Features', '{"text":"Every shape has attributes — special features that make it what it is. A triangle has 3 sides and 3 corners (angles). A rectangle has 4 sides and 4 right angles (square corners). A circle has no sides and no corners — it curves all the way around. When you know a shape''s attributes, you can find it anywhere!","items":["Triangle: 3 sides, 3 angles","Rectangle: 4 sides, 4 right angles","Square: 4 equal sides, 4 right angles","Circle: 0 sides, 0 angles, curves all around"]}', 'math_real_world', 0, 2, true, 'independent', 'any', 2, ARRAY['shapes','geometry','attributes','2.G.A.1'], ARRAY['young_scientist','explorer'], ARRAY['Identify shapes by their attributes (sides and angles)'], 3, true, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Shape Attribute Sort', 'math_real_world', 'sorting_ordering', '{"question":"Find 4 different shapes in the world around you (a window, a sign, a wheel, a roof). For each shape, count the number of sides and the number of corners (angles). Sort your shapes from fewest sides to most sides.","items":["Circle (0 sides, 0 corners)","Triangle (3 sides, 3 corners)","Rectangle/Square (4 sides, 4 corners)","Pentagon or other (5+ sides)"],"hints":["A circle has 0 sides and 0 corners","Count each straight edge as one side","Each point where sides meet is a corner (angle)","A stop sign is an octagon — 8 sides!"]}', 0, 2, 1, true, 'independent', 'any', 2, ARRAY['shapes','geometry','sorting','attributes','2.G.A.1'], ARRAY['young_scientist'], ARRAY['Sort real-world shapes by number of sides and angles'], 5, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '2.G.A.1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- 4.G.A.1: Lines, angles, shape classification (4, sketch_draw)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Lines and Angles Everywhere', '{"text":"Lines and angles are the building blocks of every structure. Parallel lines never meet (railroad tracks). Perpendicular lines meet at right angles (a plus sign). Acute angles are less than 90° (a partly open book). Obtuse angles are more than 90° (a reclining chair). Right angles are exactly 90° (a corner of a book). Architects use these to create stable, beautiful buildings.","items":["Parallel: lines that never meet (= symbol)","Perpendicular: lines meeting at 90° (+ symbol)","Acute angle: less than 90° (sharp)","Right angle: exactly 90° (square corner)","Obtuse angle: more than 90° (wide)"]}', 'math_real_world', 3, 5, true, 'independent', 'any', 5, ARRAY['lines','angles','geometry','classification','4.G.A.1'], ARRAY['explorer','urban_explorer'], ARRAY['Identify parallel, perpendicular lines and classify angles'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Angle and Line Spotter', 'math_real_world', 'sketch_draw', '{"question":"In the structures around you, find and sketch: (1) One pair of PARALLEL lines, (2) One pair of PERPENDICULAR lines, (3) One ACUTE angle, (4) One RIGHT angle, (5) One OBTUSE angle. Label each one and estimate the angle in degrees.","hints":["Parallel: look at fence rails, window frames, road lanes","Perpendicular: where a wall meets the floor, a T-intersection","Acute: rooflines, partly open doors, letter V","Obtuse: reclining benches, wide road forks, open scissors"]}', 3, 5, 2, true, 'independent', 'any', 5, ARRAY['lines','angles','sketch','geometry','4.G.A.1'], ARRAY['explorer'], ARRAY['Find and classify lines and angles in real structures'], 8, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '4.G.A.1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- HSN.Q.A.1: Units in problem solving (9-12, numeric_entry)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Units Tell the Story', '{"text":"Units are not just labels — they are essential to understanding a problem. Speed in km/h vs m/s gives completely different numbers for the same motion. Dimensional analysis (tracking units through calculations) catches errors before they matter. NASA lost a $125 million Mars orbiter because one team used metric units and another used imperial. Always track your units.","items":["Every measurement has a number AND a unit","Units must be consistent throughout a calculation","Dimensional analysis: multiply by conversion factors (1 = km/1000m)","Wrong units → wrong answer, even if the math is perfect"]}', 'math_real_world', 9, 12, true, 'independent', 'any', 8, ARRAY['units','dimensional_analysis','measurement','HSN.Q.A.1'], ARRAY['field_scientist'], ARRAY['Use units to guide problem solving and check answers'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Unit Conversion Challenge', 'math_real_world', 'numeric_entry', '{"question":"Measure the length of a nearby object in two different units: (1) your hand spans, (2) your foot lengths. Convert both to centimeters using: 1 hand span ≈ 20 cm, 1 foot length ≈ 27 cm. Do both conversions give approximately the same answer? Calculate the percentage difference between them. Which unit gave a more precise measurement?","unit":"cm (average of both methods)","hints":["Hand span: spread your hand from thumb to pinky","Measure the same object with both methods","Convert: count × conversion factor = cm","% difference = |method1 - method2| / average × 100"]}', 9, 12, 4, true, 'independent', 'any', 8, ARRAY['units','conversion','measurement','precision','HSN.Q.A.1'], ARRAY['field_scientist'], ARRAY['Apply unit conversion and assess measurement precision'], 5, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'HSN.Q.A.1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- HSS.ID.A.1: Data representation (9-12, data_collection)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Visualizing Data', '{"text":"Raw numbers are hard to understand. Data visualization transforms numbers into pictures that reveal patterns. Dot plots show individual values. Histograms show the distribution (shape) of data. Box plots show the center, spread, and outliers. Choosing the right visualization depends on your data and what question you are trying to answer.","items":["Dot plot: each dot = one value, shows individual data points","Histogram: bars show frequency of ranges (bins)","Box plot: shows median, quartiles, min, max, outliers","The shape of the distribution tells a story"]}', 'math_real_world', 9, 12, true, 'independent', 'any', 8, ARRAY['statistics','data_visualization','histogram','box_plot','HSS.ID.A.1'], ARRAY['field_scientist'], ARRAY['Choose appropriate data visualizations','Create visual representations of collected data'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Field Data Visualization', 'math_real_world', 'data_collection', '{"question":"Collect a dataset of at least 15 measurements from your environment. Choose ONE: (A) Leaf lengths from one tree, (B) Distances between fence posts/light poles, (C) Heights of people walking by, or (D) Time between passing vehicles. Then create TWO visualizations: a dot plot (every value as a dot on a number line) and describe what a histogram would look like (which range has the most values?). What is the shape: symmetric, left-skewed, or right-skewed?","hints":["Dot plot: draw a number line, place one dot per value","Histogram: group values into ranges (bins) of equal width","Symmetric: both sides look similar (bell shape)","Skewed: one tail is longer than the other"]}', 9, 12, 4, true, 'independent', 'any', 8, ARRAY['statistics','visualization','data_collection','HSS.ID.A.1'], ARRAY['field_scientist'], ARRAY['Collect field data and create appropriate visualizations'], 10, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'HSS.ID.A.1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;


