  -- D2.Geo.4.3-5: Culture and environment (3-5, short_text)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'How Culture Shapes Place', '{"text":"Culture influences how people use and change their environment. Farmers clear forests for fields. City builders pave land for roads. Different cultures build different types of homes, gardens, and public spaces. Even the names of places reflect the culture of the people who named them. When you look at any landscape, you are seeing the result of cultural choices.","items":["Agriculture: clears land, creates irrigation, changes ecosystems","Architecture: reflects climate, materials, and cultural values","Land use: parks, roads, farms — all cultural decisions","Place names: reveal who was here first and what they valued"]}', 'geography_maps', 3, 5, true, 'independent', 'any', 5, ARRAY['culture','environment','land_use','human_geography','D2.Geo.4.3-5'], ARRAY['urban_explorer','explorer'], ARRAY['Explain how culture influences environmental modification'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Cultural Landscape Reading', 'geography_maps', 'short_text', '{"question":"Look around your location. Find 3 examples of how PEOPLE (culture) have changed the ENVIRONMENT. For each example, describe: (1) What was changed, (2) Why you think it was changed, (3) What might have been here before. Examples: a sidewalk (changed natural ground for walking), a garden (changed wild land for beauty).","correct_answer":null,"hints":["Buildings replaced natural land — what grew here before?","Roads and paths show how people want to move through space","Gardens and landscaping show cultural ideas about beauty","Signs and markers show what the community values"]}', 3, 5, 2, true, 'independent', 'any', 5, ARRAY['culture','environment','observation','D2.Geo.4.3-5'], ARRAY['urban_explorer'], ARRAY['Identify cultural modifications to the environment'], 5, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'D2.Geo.4.3-5';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- D2.His.1.3-5: Chronological sequences (3-5, sorting_ordering)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Putting History in Order', '{"text":"History is the study of the past in the order it happened — chronological order. A timeline shows events from earliest to latest. Clues in buildings, streets, and landscapes tell you what came first. Older buildings have different styles than newer ones. Roads that curve often follow old paths; straight roads were planned later. Reading these clues is like being a time detective.","items":["Chronological: arranged by time (earliest first)","Timeline: a line with dates and events in order","Relative dating: this came BEFORE that (even without exact dates)","Clues: building materials, styles, and condition show age"]}', 'history_community', 3, 5, true, 'independent', 'any', 4, ARRAY['chronology','timeline','history','sequence','D2.His.1.3-5'], ARRAY['explorer','urban_explorer'], ARRAY['Create chronological sequences from environmental evidence'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Timeline Detective', 'history_community', 'sorting_ordering', '{"question":"Find 4 things at your location that were created at different times. Sort them from OLDEST to NEWEST. For each, explain your evidence for its age. Examples: an old tree (thick trunk), a new building (modern materials), a worn path (years of foot traffic), a fresh sign.","items":["Very old (50+ years): weathered stone, mature trees, old-style architecture","Old (20-50 years): established plants, worn concrete, faded paint","Recent (5-20 years): modern materials, good condition","New (less than 5 years): fresh paint, new plantings, clean materials"],"hints":["Older trees have thicker trunks and more branches","Weathered stone and faded paint suggest age","Modern materials (glass, steel, plastic) suggest newer construction","Nature reclaims human structures over time — more plants = older"]}', 3, 5, 2, true, 'independent', 'any', 4, ARRAY['chronology','sorting','history','evidence','D2.His.1.3-5'], ARRAY['urban_explorer'], ARRAY['Sort features by estimated age using evidence'], 7, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'D2.His.1.3-5';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- D2.His.3.3-5: Historical change (3-5, creative_writing)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'People Who Changed Things', '{"text":"History is shaped by individuals and groups who saw a problem and worked to fix it. Community leaders built schools and parks. Activists fought for equal rights. Engineers designed roads and bridges. Scientists discovered how to clean water. Every place you visit was shaped by people who decided to make a change. Asking WHO changed this and WHY is the heart of historical thinking.","items":["Who built this? Someone made a decision","Why was it built? A need or problem was identified","What changed because of it? Communities were affected","What might change next? History is still being made"]}', 'history_community', 3, 5, true, 'independent', 'any', 4, ARRAY['historical_change','individuals','community','D2.His.3.3-5'], ARRAY['explorer','urban_explorer'], ARRAY['Generate questions about people who shaped historical change'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Historical Change Interview', 'history_community', 'creative_writing', '{"question":"Choose one feature of your location (a building, road, park, statue, or sign). Write 5 interview questions you would ask the person who created it. Include: Why did you build this? What was here before? What problem did it solve? How has it changed the community? What do you hope it looks like in 50 years? Then write what you THINK their answers might be.","hints":["Think about the PURPOSE of what you chose — why does it exist?","Every structure replaced something that was here before","Consider the community impact — who benefits?","Imagine the future — will this still be here in 50 years?"]}', 3, 5, 2, true, 'independent', 'any', 4, ARRAY['historical_change','questions','interview','D2.His.3.3-5'], ARRAY['explorer'], ARRAY['Generate questions about individuals who shaped community change'], 8, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'D2.His.3.3-5';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- D2.His.1.6-8: Historical connections (6-8, team_debate)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Connecting Past and Present', '{"text":"Historical events do not happen in isolation — they connect to broader patterns. The neighborhood you stand in was shaped by transportation technology (horse → car → train). Its architecture reflects economic booms and busts. Its demographics reflect immigration patterns and housing policies. To understand any place, you must trace its connections to national and global history.","items":["Transportation: shaped settlement patterns","Economy: booms build, busts leave vacancies","Demographics: migration patterns shape communities","Policy: zoning laws, redlining, and public investment"]}', 'history_community', 6, 8, true, 'independent', 'any', 7, ARRAY['historical_connections','context','community','D2.His.1.6-8'], ARRAY['urban_explorer'], ARRAY['Analyze connections between local events and broader historical contexts'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Past and Present Debate', 'history_community', 'team_debate', '{"question":"Look at this area and debate: Is this place BETTER or WORSE than it was 50 years ago? Person A argues BETTER (more services, better infrastructure, progress). Person B argues WORSE (lost character, environmental impact, displacement). Person C judges based on the strength of historical evidence visible right now. Each side gets 2 minutes.","hints":["BETTER evidence: modern buildings, clean water, accessibility, technology","WORSE evidence: loss of green space, generic architecture, traffic, pollution","Consider: better for WHOM? Progress helps some and hurts others","Use visible evidence from this specific location, not general opinions"]}', 6, 8, 3, true, 'independent', 'any', 7, ARRAY['history','debate','change','D2.His.1.6-8'], ARRAY['urban_explorer'], ARRAY['Debate historical change using visible evidence'], 7, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'D2.His.1.6-8';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- D2.Civ.7.3-5: Civic participation (3-5, audio_response)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Being a Good Community Member', '{"text":"Civic virtue means caring about your community and taking action to make it better. It includes: respecting shared spaces, helping others, following rules that protect everyone, speaking up when something is unfair, and participating in community decisions. Even small actions matter — picking up litter, being kind, and listening to different viewpoints are all civic virtues.","items":["Respect: treating shared spaces and other people well","Responsibility: doing your part for the community","Participation: voting, attending meetings, volunteering","Fairness: standing up for what is right, even when hard"]}', 'history_community', 3, 5, true, 'independent', 'any', 3, ARRAY['civic','community','participation','virtue','D2.Civ.7.3-5'], ARRAY['explorer','urban_explorer'], ARRAY['Apply civic virtues in community settings'], 3, true, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Community Improvement Pitch', 'history_community', 'audio_response', '{"question":"Record a 60-second speech to your community about ONE improvement you would make to this location. Include: (1) What is the problem you see? (2) What is your solution? (3) Who would it help? (4) How could the community work together to make it happen? Use your best public speaking voice!","hints":["Start with: I would like to propose an improvement to our community...","Be specific about the problem — describe what you see","Be specific about the solution — what exactly would change?","End with a call to action: Together we can..."]}', 3, 5, 1, true, 'independent', 'any', 3, ARRAY['civic','community','speaking','proposal','D2.Civ.7.3-5'], ARRAY['explorer'], ARRAY['Propose community improvements using civic participation skills'], 5, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'D2.Civ.7.3-5';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- D2.His.14.9-12: Multiple causes/effects (9-12, short_text)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Causes and Effects Are Complex', '{"text":"Historical events rarely have a single cause or a single effect. The development of any neighborhood involved economic forces, political decisions, technological changes, demographic shifts, and cultural values — all interacting simultaneously. Historians must trace MULTIPLE causes (what led to this?) and MULTIPLE effects (what resulted from it?) to understand change. Simple explanations are almost always incomplete.","items":["Proximate cause: the immediate trigger","Distal cause: the deeper, underlying conditions","Intended effects: what people hoped would happen","Unintended effects: consequences nobody predicted"]}', 'history_community', 9, 12, true, 'independent', 'any', 9, ARRAY['causation','complexity','historical_analysis','D2.His.14.9-12'], ARRAY['urban_explorer'], ARRAY['Analyze multiple and complex causes and effects of historical events'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Causal Complexity Analysis', 'history_community', 'short_text', '{"question":"Choose one significant feature at your location (a major road, a large building, a park, a monument). Analyze it using the multiple-causation framework: (1) Name 2 proximate causes (immediate decisions that led to it), (2) Name 2 distal causes (deeper historical/economic/cultural forces), (3) Name 1 intended effect and 1 unintended effect. Write 5-7 sentences.","correct_answer":null,"hints":["Proximate: who signed the contract? who approved the zoning?","Distal: what economic conditions made it possible? what cultural values?","Intended: what was the stated purpose? (housing, commerce, recreation)","Unintended: what changed that nobody planned? (traffic, gentrification, wildlife displacement)"]}', 9, 12, 4, true, 'independent', 'any', 9, ARRAY['causation','analysis','history','complexity','D2.His.14.9-12'], ARRAY['urban_explorer'], ARRAY['Analyze multiple causes and unintended effects of historical developments'], 5, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'D2.His.14.9-12';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;


