  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Reading Signs and Displays', '{"text":"Information is presented in many ways beyond text: signs use symbols, maps use colors and lines, charts use bars and numbers, and infographics combine text with images. Being able to read and interpret all these forms of information is a key literacy skill. When you see a sign, ask: What information is it presenting? Who is the audience? What would happen if this sign were not here?","items":["Text signs: rules, directions, names","Symbol signs: no words needed (restroom, parking, warning)","Data displays: charts, graphs, tables, maps","Infographics: text + images together for quick understanding"]}', 'reading_writing', 3, 5, true, 'independent', 'any', 4, ARRAY['visual_literacy','signs','interpretation','information','RI.4.7'], ARRAY['explorer','urban_explorer'], ARRAY['Interpret information presented visually and quantitatively'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Sign and Display Reader', 'reading_writing', 'photo_observation', '{"question":"Find 3 different signs or information displays in your area. Take a photo of each. For each one, write: (1) What TYPE of information does it present? (text, symbols, numbers, map, chart), (2) Who is the AUDIENCE? (drivers, pedestrians, children, employees), (3) What is the MAIN MESSAGE? (4) How does the visual design help communicate it?","hints":["Look for: road signs, building signs, information boards, maps","Notice WHO the sign is aimed at — size and placement give clues","Symbols work across languages — that is why they are used","Consider: what would happen if this sign were removed?"]}', 3, 5, 2, true, 'independent', 'any', 4, ARRAY['visual_literacy','signs','analysis','RI.4.7'], ARRAY['explorer'], ARRAY['Analyze how visual and quantitative information is presented'], 7, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = 'RI.4.7';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;


  -- ═══════════════════════════════════════════════════════════
