  -- 3.1.1: Forces — balanced/unbalanced (3, numeric_entry)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'Push, Pull, Balance', '{"text":"Forces are pushes and pulls that make things move, stop, or change direction. When forces are balanced (equal in opposite directions), nothing moves — like a book sitting on a table. When forces are unbalanced (one is stronger), things move — like pushing a swing. Gravity always pulls things down. Friction pushes back against movement. Understanding forces helps us explain why everything moves (or doesn''t).","items":["Force: a push or pull on an object","Balanced forces: equal and opposite → no movement","Unbalanced forces: one is stronger → movement","Gravity: always pulls toward Earth''s center"]}', 'science_nature', 3, 5, true, 'independent', 'any', 4, ARRAY['forces','push','pull','balance','3.1.1'], ARRAY['field_scientist','young_scientist'], ARRAY['Identify balanced and unbalanced forces','Predict motion from force analysis'], 3, true, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Force Finder', 'science_nature', 'numeric_entry', '{"question":"Find a flat surface (sidewalk, table, bench). Place a small object (rock, leaf, pen) on it. (1) Is the object moving? What balanced forces keep it still? (2) Give it a gentle push. How many centimeters does it slide? (3) Now push harder. How far does it go this time? (4) Which surface nearby would create the most friction (rough) vs least friction (smooth)? Compare slide distances.","unit":"cm (hard push distance)","hints":["Balanced forces: gravity pulls down, the surface pushes up","Your push creates an unbalanced force → the object moves","Friction is the force that slows it down","Rougher surfaces = more friction = shorter slide"]}', 3, 5, 2, true, 'independent', 'any', 4, ARRAY['forces','friction','measurement','3.1.1'], ARRAY['field_scientist'], ARRAY['Investigate balanced and unbalanced forces through measurement'], 5, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '3.1.1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

  -- 4.1.1: Light and vision (4, multiple_choice)
  p := gen_random_uuid(); t := gen_random_uuid();
  INSERT INTO public.primers (id, title, content, subject_domain, grade_range_min, grade_range_max, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, primer_reveals_location, created_by) VALUES
    (p, 'How We See Things', '{"text":"You see objects because light bounces off them and enters your eyes. The sun or a lamp produces light. That light hits an object and reflects (bounces) in all directions. Some of that reflected light enters your eyes, which send a signal to your brain. Without light, you cannot see anything — that is why dark rooms are dark. The color you see depends on which wavelengths of light the object reflects vs absorbs.","items":["Light source: produces light (sun, lamp, screen)","Reflection: light bounces off objects","Your eye: receives reflected light","Your brain: interprets the signals as images"]}', 'science_nature', 3, 5, true, 'independent', 'any', 4, ARRAY['light','vision','reflection','physics','4.1.1'], ARRAY['field_scientist'], ARRAY['Explain that we see objects because reflected light enters our eyes'], 3, false, u_owner);
  INSERT INTO public.tasks (id, title, subject_domain, challenge_type, content, grade_range_min, grade_range_max, difficulty_level, is_library, location_dependency, location_type, difficulty_rating, tags, themes, learning_objectives, estimated_minutes, created_by) VALUES
    (t, 'Light Path Tracer', 'science_nature', 'multiple_choice', '{"question":"You can see a tree in front of you. What is the correct order of events that lets you see it?","options":["Sunlight hits the tree → light reflects off the tree → reflected light enters your eyes → your brain creates an image","Your eyes send light to the tree → the tree glows → you see it","The tree produces its own light → the light enters your eyes","Your brain imagines the tree → your eyes confirm it"],"correct_answer":"Sunlight hits the tree → light reflects off the tree → reflected light enters your eyes → your brain creates an image","hints":["Objects do NOT produce their own light (unless they glow)","Light always travels FROM a source TO objects TO your eyes","Your eyes RECEIVE light, they do not SEND it","The brain processes the signals — vision happens in the brain, not the eyes"]}', 3, 5, 2, true, 'independent', 'any', 4, ARRAY['light','vision','reflection','sequence','4.1.1'], ARRAY['field_scientist'], ARRAY['Identify the correct sequence of light reflection and vision'], 3, u_owner);
  SELECT id INTO std_id FROM public.education_standards WHERE code = '4.1.1';
  IF std_id IS NOT NULL THEN
    INSERT INTO public.task_standard_alignments (task_id, standard_id, alignment_strength) VALUES (t, std_id, 'primary') ON CONFLICT DO NOTHING;
    INSERT INTO public.primer_standard_alignments (primer_id, standard_id, alignment_strength) VALUES (p, std_id, 'primary') ON CONFLICT DO NOTHING;
  END IF;

